    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT external_connection_history_change_type_check CHECK (((change_type)::text = ANY ((ARRAY['first_seen'::character varying, 'cert_rotated'::character varying, 'cipher_changed'::character varying, 'protocol_upgraded'::character varying, 'protocol_downgraded'::character varying, 'crypto_strength_changed'::character varying])::text[])))
);


-- TABLE: external_connections
CREATE TABLE IF NOT EXISTS public.external_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    source_ip inet NOT NULL,
    source_hostname character varying(255),
    source_asset_id uuid,
    dest_ip inet NOT NULL,
    dest_hostname character varying(255),
    dest_port integer NOT NULL,
    protocol character varying(50) NOT NULL,
    protocol_version character varying(50),
    cipher_suite character varying(255),
    key_exchange_algorithm character varying(100),
    key_size integer,
    supported_tls_versions text[],
    crypto_strength character varying(20),
    is_pqc_resistant boolean DEFAULT false NOT NULL,
    weak_reasons text[] DEFAULT '{}'::text[],
    cert_subject character varying(500),
    cert_issuer character varying(500),
    cert_san text[],
    cert_not_before timestamp with time zone,
    cert_not_after timestamp with time zone,
    cert_fingerprint_sha256 character varying(64),
    cert_public_key_algorithm character varying(50),
    cert_public_key_size integer,
    cert_signature_algorithm character varying(100),
    cert_is_expired boolean DEFAULT false NOT NULL,
    cert_validation_status character varying(30),
    cert_pem text,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    observation_count bigint DEFAULT 1 NOT NULL,
    sensor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    service_name character varying(100),
    service_version character varying(100),
    service_confidence character varying(20),
    service_identification_method character varying(50),
    -- Non-null once a tenant promotes a 3rd-party connection to a managed asset
    --links the connection to that asset. App-managed, no FK: `assets`
    -- is hash-partitioned and soft-deleted.
    elevated_asset_id uuid,
    -- The endpoint of OUR asset the connection leaves from (DATA_MODEL §2).
    -- source_asset_id stays and is the roll-up target.
    --
    -- It is NULL for everything phase 1 writes, and that is a decision rather
    -- than an omission: an outbound connection leaves from an EPHEMERAL socket,
    -- which no producer observes and which is not an inventoried endpoint. The
    -- listening endpoint of the same asset is a different socket, and linking to
    -- it would assert a measurement nobody made. A producer that does report a
    -- source port (a host agent watching its own connections, ADR-0004 D3) fills
    -- it in.
    source_endpoint_id uuid,
    -- Provenance of dest_hostname (ADR-0005 source_kind vocabulary), so the
    -- upsert can tell a MEASURED name from an INFERRED one.
    --
    -- `measured` is a name that came off the wire — the TLS SNI the client
    -- itself asked for, a DHCP/mDNS/NetBIOS name the host announced.
    -- `inferred` is a guess about the address made by someone else, in
    -- practice a reverse-DNS PTR answer. The two used to be indistinguishable
    -- once written, so an `ec2-…compute-1.amazonaws.com` PTR happily
    -- overwrote a captured `slack.com` on the next observation of the same
    -- flow: not empty, so "empty never wins" did not stop it.
    --
    -- NULL means "written before this column existed, or by a producer that
    -- does not state its provenance" — deliberately a third state, not folded
    -- into either answer. See the precedence ladder in
    -- ExternalConnectionsService.Upsert.
    dest_hostname_source_kind character varying(20),
    -- The sensor-level certificate quality flags (cert_has_sct, cert_no_subject,
    -- cert_validation_status="untrusted_ca"/"incomplete_chain"). They are
    -- certificate-hygiene observations, not cryptographic weakness, so they live
    -- here and NOT in weak_reasons, where they would inflate the "weak crypto"
    -- tile with TLS 1.3/AES-256-GCM connections whose only flaw was a missing
    -- SCT. Non-scoring. cert_sct_source mirrors certificates.sct_source.
    cert_hygiene_flags text[] DEFAULT '{}'::text[],
    cert_sct_source character varying(20),
    -- The tenant's verdict on the leaf a 3rd-party server presented (same
    -- vocabulary as certificates.trust_status), so the 3rd Party lens reads the
    -- organisation's trust decisions rather than the probing runtime's OS store.
    -- NULL = not evaluated (no certificate presented).
    trust_status character varying(20),
    CONSTRAINT external_connections_strength_v2_check CHECK (crypto_strength IS NULL OR crypto_strength IN ('weak', 'acceptable', 'strong', 'recommended')),
    CONSTRAINT external_connections_dest_hostname_source_kind_check CHECK ((dest_hostname_source_kind IS NULL OR (dest_hostname_source_kind)::text = ANY ((ARRAY['measured'::character varying, 'imported'::character varying, 'declared'::character varying, 'inferred'::character varying])::text[]))),
    CONSTRAINT external_connections_dest_port_check CHECK (((dest_port >= 1) AND (dest_port <= 65535))),
    CONSTRAINT external_connections_trust_status_check CHECK ((trust_status IS NULL) OR ((trust_status)::text = ANY ((ARRAY['public'::character varying, 'private_trusted'::character varying, 'self_signed'::character varying, 'untrusted'::character varying, 'distrusted'::character varying, 'incomplete'::character varying])::text[])))
);


