-- TABLE ATTACH: activity_logs_y2026m04
DO $$ BEGIN
  IF to_regclass('audit.activity_logs') IS NOT NULL
     AND to_regclass('audit.activity_logs_y2026m04') IS NOT NULL
     AND NOT EXISTS (
