DO $$ BEGIN
  IF to_regclass('public.ssh_keys') IS NOT NULL
     AND to_regclass('public.assets') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM pg_constraint
       WHERE conname = 'ssh_keys_tenant_asset_fkey' AND conrelid = to_regclass('public.ssh_keys')
